278→// AreHooksInstalled checks if Entire hooks are installed.
279→func (c *CursorAgent) AreHooksInstalled() bool {
280→	worktreeRoot, err := paths.WorktreeRoot()
281→	if err != nil {
282→		worktreeRoot = "."
283→	}
284→	hooksPath := filepath.Join(worktreeRoot, ".cursor", HooksFileName)
285→	data, err := os.ReadFile(hooksPath) //nolint:gosec // path is constructed from repo root + fixed path
286→	if err != nil {
287→		return false
288→	}
289→
290→	var hooksFile CursorHooksFile
291→	if err := json.Unmarshal(data, &hooksFile); err != nil {
292→		return false
293→	}
294→
295→	return hasEntireHook(hooksFile.Hooks.SessionStart) ||
296→		hasEntireHook(hooksFile.Hooks.SessionEnd) ||
297→		hasEntireHook(hooksFile.Hooks.BeforeSubmitPrompt) ||
298→		hasEntireHook(hooksFile.Hooks.Stop) ||
299→		hasEntireHook(hooksFile.Hooks.PreCompact) ||
300→		hasEntireHook(hooksFile.Hooks.SubagentStart) ||
301→		hasEntireHook(hooksFile.Hooks.SubagentStop)
302→}
