  1→// Package cursor implements the Agent interface for Cursor.
  2→package cursor
  3→
  4→import (
  5→	"errors"
  6→	"fmt"
  7→	"os"
  8→	"path/filepath"
  9→	"regexp"
 10→	"time"
 11→
 12→	"github.com/entireio/cli/cmd/entire/cli/agent"
 13→	"github.com/entireio/cli/cmd/entire/cli/paths"
 14→)
 15→
 16→//nolint:gochecknoinits // Agent self-registration is the intended pattern
 17→func init() {
 18→	agent.Register(agent.AgentNameCursor, NewCursorAgent)
 19→}
 20→
 21→// CursorAgent implements the Agent interface for Cursor IDE.
 22→//
 23→//nolint:revive // CursorAgent is clearer than Agent in this context
 24→type CursorAgent struct{}
 25→
 26→// NewCursorAgent creates a new Cursor agent instance.
 27→func NewCursorAgent() agent.Agent {
 28→	return &CursorAgent{}
 29→}
 30→
 31→// Name returns the agent registry key.
 32→func (c *CursorAgent) Name() agent.AgentName {
 33→	return agent.AgentNameCursor
 34→}
 35→
 36→// Type returns the agent type identifier.
 37→func (c *CursorAgent) Type() agent.AgentType {
 38→	return agent.AgentTypeCursor
 39→}
 40→
 41→// Description returns a human-readable description.
 42→func (c *CursorAgent) Description() string {
 43→	return "Cursor - AI-powered code editor"
 44→}
 45→
 46→func (c *CursorAgent) IsPreview() bool { return true }
 47→
 48→// DetectPresence checks if Cursor is configured in the repository.
 49→func (c *CursorAgent) DetectPresence() (bool, error) {
 50→	worktreeRoot, err := paths.WorktreeRoot()
 51→	if err != nil {
 52→		worktreeRoot = "."
 53→	}
 54→
 55→	cursorDir := filepath.Join(worktreeRoot, ".cursor")
 56→	if _, err := os.Stat(cursorDir); err == nil {
 57→		return true, nil
 58→	}
 59→	return false, nil
 60→}
 61→
 62→// GetSessionID extracts the session ID from hook input.
 63→func (c *CursorAgent) GetSessionID(input *agent.HookInput) string {
 64→	return input.SessionID
 65→}
 66→
 67→// ResolveSessionFile returns the path to a Cursor session file.
 68→// Cursor uses JSONL format like Claude Code.
 69→func (c *CursorAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
 70→	return filepath.Join(sessionDir, agentSessionID+".jsonl")
 71→}
 72→
 73→// ProtectedDirs returns directories that Cursor uses for config/state.
 74→func (c *CursorAgent) ProtectedDirs() []string { return []string{".cursor"} }
 75→
 76→// GetSessionDir returns the directory where Cursor stores session transcripts.
 77→func (c *CursorAgent) GetSessionDir(repoPath string) (string, error) {
 78→	if override := os.Getenv("ENTIRE_TEST_CURSOR_PROJECT_DIR"); override != "" {
 79→		return override, nil
 80→	}
 81→
 82→	homeDir, err := os.UserHomeDir()
 83→	if err != nil {
 84→		return "", fmt.Errorf("failed to get home directory: %w", err)
 85→	}
 86→
 87→	projectDir := sanitizePathForCursor(repoPath)
 88→	return filepath.Join(homeDir, ".cursor", "projects", projectDir), nil
 89→}
 90→
 91→// ReadSession reads a session from Cursor's storage (JSONL transcript file).
 92→// Note: ModifiedFiles is left empty because Cursor's transcript format does not
 93→// contain tool_use blocks. File detection relies on git status instead.
 94→func (c *CursorAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
 95→	if input.SessionRef == "" {
 96→		return nil, errors.New("session reference (transcript path) is required")
 97→	}
 98→
 99→	data, err := os.ReadFile(input.SessionRef)
100→	if err != nil {
101→		return nil, fmt.Errorf("failed to read transcript: %w", err)
102→	}
103→
104→	return &agent.AgentSession{
105→		SessionID:  input.SessionID,
106→		AgentName:  c.Name(),
107→		SessionRef: input.SessionRef,
108→		StartTime:  time.Now(),
109→		NativeData: data,
110→	}, nil
111→}
112→
113→// WriteSession writes a session to Cursor's storage (JSONL transcript file).
114→func (c *CursorAgent) WriteSession(session *agent.AgentSession) error {
115→	if session == nil {
116→		return errors.New("session is nil")
117→	}
118→
119→	if session.AgentName != "" && session.AgentName != c.Name() {
120→		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
121→	}
122→
123→	if session.SessionRef == "" {
124→		return errors.New("session reference (transcript path) is required")
125→	}
126→
127→	if len(session.NativeData) == 0 {
128→		return errors.New("session has no native data to write")
129→	}
130→
131→	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
132→		return fmt.Errorf("failed to write transcript: %w", err)
133→	}
134→
135→	return nil
136→}
137→
138→// FormatResumeCommand returns an instruction to resume a Cursor session.
139→// Cursor is a GUI IDE, so there's no CLI command to resume a session directly.
140→func (c *CursorAgent) FormatResumeCommand(_ string) string {
141→	return "Open this project in Cursor IDE to continue the session."
142→}
143→
144→// sanitizePathForCursor converts a path to Cursor's project directory format.
145→var nonAlphanumericRegex = regexp.MustCompile(`[^a-zA-Z0-9]`)
146→
147→func sanitizePathForCursor(path string) string {
148→	return nonAlphanumericRegex.ReplaceAllString(path, "-")
149→}
150→
151→// ChunkTranscript splits a JSONL transcript at line boundaries.
152→func (c *CursorAgent) ChunkTranscript(content []byte, maxSize int) ([][]byte, error) {
153→	chunks, err := agent.ChunkJSONL(content, maxSize)
154→	if err != nil {
155→		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
156→	}
157→	return chunks, nil
158→}
159→
160→// ReassembleTranscript concatenates JSONL chunks with newlines.
161→func (c *CursorAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
162→	return agent.ReassembleJSONL(chunks), nil
163→}
