  1→// Package settings provides configuration loading for Entire.
  2→// This package is separate from cli to allow strategy package to import it
  3→// without creating an import cycle (cli imports strategy).
  4→package settings
  5→
  6→import (
  7→	"bytes"
  8→	"context"
  9→	"encoding/json"
 10→	"fmt"
 11→	"io"
 12→	"os"
 13→	"path/filepath"
 14→
 15→	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
 16→	"github.com/entireio/cli/cmd/entire/cli/paths"
 17→)
 18→
 19→const (
 20→	// EntireSettingsFile is the path to the Entire settings file
 21→	EntireSettingsFile = ".entire/settings.json"
 22→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
 23→	EntireSettingsLocalFile = ".entire/settings.local.json"
 24→)
 25→
 26→// EntireSettings represents the .entire/settings.json configuration
 27→type EntireSettings struct {
 28→
 29→	// Enabled indicates whether Entire is active. When false, CLI commands
 30→	// show a disabled message and hooks exit silently. Defaults to true.
 31→	Enabled bool `json:"enabled"`
 32→
 33→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
 34→	// This is used for development when the binary is not installed
 35→	LocalDev bool `json:"local_dev,omitempty"`
 36→
 37→	// LogLevel sets the logging verbosity (debug, info, warn, error).
 38→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
 39→	// Defaults to "info".
 40→	LogLevel string `json:"log_level,omitempty"`
 41→
 42→	// StrategyOptions contains strategy-specific configuration
 43→	StrategyOptions map[string]any `json:"strategy_options,omitempty"`
 44→
 45→	// Telemetry controls anonymous usage analytics.
 46→	// nil = not asked yet (show prompt), true = opted in, false = opted out
 47→	Telemetry *bool `json:"telemetry,omitempty"`
 48→
 49→	// Deprecated: no longer used. Exists to tolerate old settings files
 50→	// that still contain "strategy": "auto-commit" or similar.
 51→	Strategy string `json:"strategy,omitempty"`
 52→}
 53→
 54→// Load loads the Entire settings from .entire/settings.json,
 55→// then applies any overrides from .entire/settings.local.json if it exists.
 56→// Returns default settings if neither file exists.
 57→// Works correctly from any subdirectory within the repository.
 58→func Load(ctx context.Context) (*EntireSettings, error) {
 59→	// Get absolute paths for settings files
 60→	settingsFileAbs, err := paths.AbsPath(ctx, EntireSettingsFile)
 61→	if err != nil {
 62→		settingsFileAbs = EntireSettingsFile // Fallback to relative
 63→	}
