100→func loadFromFile(filePath string) (*EntireSettings, error) {
101→	settings := &EntireSettings{
102→		Enabled: true, // Default to enabled
103→	}
104→
105→	data, err := os.ReadFile(filePath) //nolint:gosec // path is from caller
106→	if err != nil {
107→		if os.IsNotExist(err) {
108→			return settings, nil
109→		}
110→		return nil, fmt.Errorf("%w", err)
111→	}
112→
113→	dec := json.NewDecoder(bytes.NewReader(data))
114→	dec.DisallowUnknownFields()
115→	if err := dec.Decode(settings); err != nil {
116→		return nil, fmt.Errorf("parsing settings file: %w", err)
117→	}
118→
