122→// mergeJSON merges JSON data into existing settings.
123→// Only non-zero values from the JSON override existing settings.
124→func mergeJSON(settings *EntireSettings, data []byte) error {
125→	// First, validate that there are no unknown keys using strict decoding
126→	dec := json.NewDecoder(bytes.NewReader(data))
127→	dec.DisallowUnknownFields()
128→	var temp EntireSettings
129→	if err := dec.Decode(&temp); err != nil {
130→		return fmt.Errorf("parsing JSON: %w", err)
131→	}
132→
133→	// Parse into a map to check which fields are present
134→	var raw map[string]json.RawMessage
135→	if err := json.Unmarshal(data, &raw); err != nil {
136→		return fmt.Errorf("parsing JSON: %w", err)
137→	}
138→
139→	// Override enabled if present
140→	if enabledRaw, ok := raw["enabled"]; ok {
141→		var e bool
142→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
143→			return fmt.Errorf("parsing enabled field: %w", err)
144→		}
145→		settings.Enabled = e
146→	}
147→
148→	// Override local_dev if present
149→	if localDevRaw, ok := raw["local_dev"]; ok {
150→		var ld bool
151→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
152→			return fmt.Errorf("parsing local_dev field: %w", err)
153→		}
154→		settings.LocalDev = ld
155→	}
156→
157→	// Override log_level if present and non-empty
158→	if logLevelRaw, ok := raw["log_level"]; ok {
159→		var ll string
160→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
161→			return fmt.Errorf("parsing log_level field: %w", err)
162→		}
163→		if ll != "" {
164→			settings.LogLevel = ll
165→		}
166→	}
167→
168→	// Merge strategy_options if present
169→	if optionsRaw, ok := raw["strategy_options"]; ok {
170→		var opts map[string]any
171→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
172→			return fmt.Errorf("parsing strategy_options field: %w", err)
173→		}
174→		if settings.StrategyOptions == nil {
175→			settings.StrategyOptions = opts
176→		} else {
177→			for k, v := range opts {
178→				settings.StrategyOptions[k] = v
179→			}
180→		}
181→	}
182→
183→	// Override telemetry if present
184→	if telemetryRaw, ok := raw["telemetry"]; ok {
185→		var t bool
186→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
187→			return fmt.Errorf("parsing telemetry field: %w", err)
188→		}
189→		settings.Telemetry = &t
190→	}
191→
192→	return nil
193→}
