346→// resolveWorktreeBranch resolves the current branch for a worktree path
347→// by reading the HEAD ref directly from the filesystem
348→func resolveWorktreeBranch(worktreePath string) string {
349→	gitPath := filepath.Join(worktreePath, ".git")
350→
351→	fi, err := os.Stat(gitPath)
352→	if err != nil {
353→		return ""
354→	}
355→
356→	var headPath string
357→	if fi.IsDir() {
358→		// Regular repo: .git is a directory
359→		headPath = filepath.Join(gitPath, "HEAD")
360→	} else {
361→		// Worktree: .git is a file containing "gitdir: <path>"
362→		data, err := os.ReadFile(gitPath) //nolint:gosec // path derived from known worktree dir
363→		if err != nil {
364→			return ""
365→		}
366→		content := strings.TrimSpace(string(data))
367→		if !strings.HasPrefix(content, "gitdir: ") {
368→			return ""
369→		}
370→		gitdirPath := strings.TrimPrefix(content, "gitdir: ")
371→		if !filepath.IsAbs(gitdirPath) {
372→			gitdirPath = filepath.Join(worktreePath, gitdirPath)
373→		}
374→		headPath = filepath.Join(gitdirPath, "HEAD")
375→	}
376→
377→	data, err := os.ReadFile(headPath) //nolint:gosec // path constructed from .git/HEAD
378→	if err != nil {
379→		return ""
380→	}
381→
382→	ref := strings.TrimSpace(string(data))
383→
384→	// Symbolic ref: "ref: refs/heads/<branch>"
385→	if strings.HasPrefix(ref, "ref: refs/heads/") {
386→		branch := strings.TrimPrefix(ref, "ref: refs/heads/")
387→		// Reftable ref storage uses "ref: refs/heads/.invalid" as a dummy HEAD stub.
388→		// Fall back to git to resolve the actual branch in that case.
389→		if branch == ".invalid" {
390→			return resolveWorktreeBranchGit(worktreePath)
391→		}
392→		return branch
393→	}
394→
395→	// Detached HEAD or other ref type
396→	return detachedHEADDisplay
397→}
