399→// resolveWorktreeBranchGit resolves the branch name by shelling out to git.
400→// Used as a fallback for reftable ref storage where .git/HEAD is a stub.
401→func resolveWorktreeBranchGit(worktreePath string) string {
402→	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
403→	defer cancel()
404→	cmd := exec.CommandContext(ctx, "git", "-C", worktreePath, "rev-parse", "--symbolic-full-name", "HEAD")
405→	out, err := cmd.Output()
406→	if err != nil {
407→		return detachedHEADDisplay
408→	}
409→	ref := strings.TrimSpace(string(out))
410→	if strings.HasPrefix(ref, "refs/heads/") {
411→		return strings.TrimPrefix(ref, "refs/heads/")
412→	}
413→	return detachedHEADDisplay
414→}
